L4_1.m_CharStrID = L5_1
L5_1 = "탐미엘에게 그 본질을 빼앗기고, 그 껍데기만 남아버린 신성의 잔재."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "タミエルにその本質を奪われ、抜け殻だけが残った神聖の残滓。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Stripped of its essence by Tammiel, what remains is a hollow shell, a remnant of the Divinity."
