L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "世界の防衛機制として彼らがここに現れたということは、ここに通路が存在するということ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Their appearance here as the world's defense mechanism implies that a passage exists in this location."
