L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "이렇게 어린 늑대가, 그것도 단신으로 내 앞에 나타날 줄은 몰랐는데 말이야."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "こんな幼いオオカミが、それもたった1人で私の前に現れるなんて。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I didn't expect a young Wolf like you to show up before me, especially alone."
L45_1.m_Talk_ENG = L46_1
L46_1 = "真沒想到，這麼小的狼，竟然單槍匹馬出現在我的面前。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "真没想到，这么小的狼，竟然单枪匹马出现在我的面前。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "I didn't expect a young Wolf like you to show up before me, especially alone."
