L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "원래라면 당신은 이쯤에서 프로토콜 – CoW를 발동. 다음 세계를 기약하겠죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "本来ならあなたはこの辺りでプロトコルCoWを発動し、次の世界を期するでしょう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Normally, this is where you'd execute Protocol: CoW and prepare for the next world."
L33_1.m_Talk_ENG = L34_1
L34_1 = "這個時候你應該啟動CoW抑制協議了。請期待下一個世界吧。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "这个时候您应该启动CoW抑制协议了。请期待下一个世界吧。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Normally, this is where you'd execute Protocol: CoW and prepare for the next world."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Normally, this is where you'd execute Protocol: CoW and prepare for the next world."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP13_ACT1_PROLOGUE2@122#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 580
L34_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "하지만 이 세계는 정해진 인과로부터 1.000000%만큼의 오차율이 쌓여버린 세계."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "しかしこの世界は決められた因果から、1.000000%の誤差率が蓄積されてしまった世界。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "However, this world exhibits a 1.000000% deviation from its determined causality."
L34_1.m_Talk_ENG = L35_1
L35_1 = "但是這個世界是由既定的因果關係累積了1.000000%的誤差率所構成的世界。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "但是这个世界是由既定的因果关系累积了1.000000%的误差率所构成的世界。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "However, this world exhibits a 1.000000% deviation from its determined causality."
L34_1.m_Talk_DEU = L35_1
L35_1 = "However, this world exhibits a 1.000000% deviation from its determined causality."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
