L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 580
L35_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "만약 이 세계가 지나가 버린 세계들과 다른 결과를 맞이한다면."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "もしこの世界が、過ぎ去った他の世界と異なる結末を迎えるのなら。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "If this world is to meet a different end than all those that came before,"
L35_1.m_Talk_ENG = L36_1
L36_1 = "如果這個世界迎來了與過去世界不同的結果。"
