L44_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "같은 신성이지만, 클리파 타입 에너지와는 정반대되는 성질을 가진 에너지……."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "同じく神聖でありながら、クリファタイプのエネルギーとは真逆の性質を持つエネルギー……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It's still a Divinity energy in origin... but its nature is completely opposite to that of the Qlipha type..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "雖然同為神性，但這種能量與逆卡巴拉類型的能量性質完全相反……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "虽然同为神性，但这种能量与逆卡巴拉类型的能量性质完全相反……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "It's still a Divinity energy in origin... but its nature is completely opposite to that of the Qlipha type..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "It's still a Divinity energy in origin... but its nature is completely opposite to that of the Qlipha type..."
L43_1.m_Talk_FRA = L44_1
