L45_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "틀림없이 이 힘의 개입으로 시공간 종료 직전 현실이 개변. 분기점을 생성한 것이겠지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "間違いなくこの力の介入によって、時空間終了直前の現実が改変され、分岐点が生成されたのだろう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "No doubt, this force's intervention changed reality just before the collapse of spacetime, creating a new turning point."
L44_1.m_Talk_ENG = L45_1
L45_1 = "毫無疑問，是這股力量的介入在時空結束前改變了現實。應該是它創造了分歧點。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "毫无疑问，是这股力量的介入在时空结束前改变了现实。应该是它创造了分歧点。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "No doubt, this force's intervention changed reality just before the collapse of spacetime, creating a new turning point."
L44_1.m_Talk_DEU = L45_1
