L48_1 = "EP13_ACT1_PROLOGUE2@163#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 580
L47_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "미약하지만, 유기체처럼 일정한 패턴과 리듬으로 파장이 고동치고 있어."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "微弱ながら、有機体のように一定したパターンとリズムで波形を形作っている。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It's faint, but the wavelength pulses with a steady pattern and rhythm, almost like a living organism."
L47_1.m_Talk_ENG = L48_1
L48_1 = "雖然微弱，但波動像有機體一樣以一定的模式和節奏跳動著。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "虽然微弱，但波动像有机体一样以一定的模式和节奏跳动着。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "It's faint, but the wavelength pulses with a steady pattern and rhythm, almost like a living organism."
L47_1.m_Talk_DEU = L48_1
L48_1 = "It's faint, but the wavelength pulses with a steady pattern and rhythm, almost like a living organism."
L47_1.m_Talk_FRA = L48_1
