L49_1 = "EP13_ACT1_PROLOGUE2@164#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 580
L48_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "인류가 최초로 세피라 포인트와 접촉했을 때 수신했던 정체불명의 신호."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "人類が初めてセフィラポイントと接触した際に受信した、正体不明の信号。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "The unidentified signal humanity received when it first came into contact with the Sephira Point."
L48_1.m_Talk_ENG = L49_1
L49_1 = "人類首次接觸到生命樹質點時收到的不明訊號。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "人类首次接触到塞菲拉点时收到的不明信号。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "The unidentified signal humanity received when it first came into contact with the Sephira Point."
L48_1.m_Talk_DEU = L49_1
L49_1 = "The unidentified signal humanity received when it first came into contact with the Sephira Point."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP13_ACT1_PROLOGUE2@165#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 580
L49_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "대기가 존재하지 않는 달의 뒷면에서 들려오는, 들릴 리 없는 기이한 노랫소리……."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "大気が存在しない月の裏側から聞こえてくる、聞こえるはずのない奇妙な歌声……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "A strange song, echoing from the dark side of the moon, where no atmosphere exists... and no sound should be heard..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "從沒有大氣存在的月球背面傳來的，不可能聽到的奇異歌聲……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "从没有大气存在的月球背面传来的，不可能听到的奇异歌声……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "A strange song, echoing from the dark side of the moon, where no atmosphere exists... and no sound should be heard..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "A strange song, echoing from the dark side of the moon, where no atmosphere exists... and no sound should be heard..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP13_ACT1_PROLOGUE2@166#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 250
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 580
L50_1.m_CutScenStrID = "EP13_ACT1_PROLOGUE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "그렇군, 그건 단순히 인간의 주관적 해석이 섞인, 비유적인 표현이 아니었어."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "なるほど、あれは人間の主観的解釈が混じった、単なる比喩的表現ではなかった。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "So that was no metaphor clouded by human subjectivity. It was real."
L50_1.m_Talk_ENG = L51_1
L51_1 = "原來如此，那並不是單純摻雜了人類主觀解釋的比喻性表達。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "原来如此，那并不是单纯掺杂了人类主观解释的比喻性表达。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "So that was no metaphor clouded by human subjectivity. It was real."
L50_1.m_Talk_DEU = L51_1
L51_1 = "So that was no metaphor clouded by human subjectivity. It was real."
L50_1.m_Talk_FRA = L51_1
