L5_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "우주에 울려 퍼지는 이 노랫소리야 말로, 모든 차원의 평행 세계가 그토록 염원했던 1.000000%의 희망."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "宇宙に響き渡るこの歌声こそが、あらゆる次元のパラレルワールドが願ってやまなかった1.000000%の希望。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "This song echoing through the outer space... this is the 1.000000% hope that every parallel world across all dimensions has longed for."
L4_1.m_Talk_ENG = L5_1
L5_1 = "在宇宙中回蕩的這首歌聲，正是所有次元平行世界所渴望的1.000000%的希望。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "在宇宙中回荡的这首歌声，正是所有维度平行世界所渴望的1.000000%的希望。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "This song echoing through the outer space... this is the 1.000000% hope that every parallel world across all dimensions has longed for."
L4_1.m_Talk_DEU = L5_1
L5_1 = "This song echoing through the outer space... this is the 1.000000% hope that every parallel world across all dimensions has longed for."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
