L6_1 = "ASIMOV_QLIPHOTH_NPC_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "세피로트 나무가… 세계 그 자체가 의지를 품고 있다는 증거겠죠."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "セフィロトが……世界そのものが意思を持っているという証拠でしょう。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "It's proof that the Tree of Sephiroth... that the world itself holds a will of its own."
L5_1.m_Talk_ENG = L6_1
L6_1 = "生命樹……這就是世界本身擁有意志的證據吧。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "塞菲罗特之树……这就是世界本身拥有意志的证据吧。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "It's proof that the Tree of Sephiroth... that the world itself holds a will of its own."
L5_1.m_Talk_DEU = L6_1
L6_1 = "It's proof that the Tree of Sephiroth... that the world itself holds a will of its own."
L5_1.m_Talk_FRA = L6_1
